// 由 tool/src/roots/static-roots.h.js 从 v8/src/roots/static-roots.h + static-roots-{intl,nointl}-{wasm,nowasm}.h 生成; 修订就地改, 复跑覆盖
// 静态只读根地址表 (tools/dev/gen-static-roots.py 产物, 此处再机械转写)

/// 静态根布局选择矩阵 (原版 static-roots.h 的 #if 展开):
